package org.apache.commons.lang.text;

import java.io.*;
import java.io.Reader;
import java.io.Writer;
import java.math.*;
import java.util.*;
import java.util.Collection;
import java.util.Iterator;
import java.util.List;
import org.apache.commons.lang.ArrayUtils;
import org.apache.commons.lang.SystemUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for StrBuilder.contains(char ch)
 */
public class StrBuilder_contains_TriageGen2Test {

    @Test
    public void testContains_EmptyBuilder_ReturnsFalse() {
        StrBuilder sb = new StrBuilder();
        assertFalse("Should return false for empty builder", sb.contains('a'));
    }

    @Test
    public void testContains_CharExists_ReturnsTrue() {
        StrBuilder sb = new StrBuilder("hello");
        assertTrue("Should return true when character exists", sb.contains('e'));
        assertTrue("Should return true when character is at start", sb.contains('h'));
        assertTrue("Should return true when character is at end", sb.contains('o'));
    }

    @Test
    public void testContains_CharDoesNotExist_ReturnsFalse() {
        StrBuilder sb = new StrBuilder("abc");
        assertFalse("Should return false when character does not exist", sb.contains('z'));
    }

    @Test
    public void testContains_SingleCharMatch_ReturnsTrue() {
        StrBuilder sb = new StrBuilder("a");
        assertTrue("Should return true for single character match", sb.contains('a'));
    }

    @Test
    public void testContains_DuplicateChars_ReturnsTrue() {
        StrBuilder sb = new StrBuilder("banana");
        assertTrue("Should return true even if character appears multiple times", sb.contains('a'));
    }

    @Test
    public void testContains_CaseSensitivity() {
        StrBuilder sb = new StrBuilder("Java");
        assertTrue("Should find lowercase 'a'", sb.contains('a'));
        assertFalse("Should not find uppercase 'A' if only lowercase exists", sb.contains('A'));
    }

    @Test
    public void testContains_SpecialCharacters() {
        StrBuilder sb = new StrBuilder("!@#$%^&*()");
        assertTrue("Should find special character '@'", sb.contains('@'));
        assertTrue("Should find special character '!'", sb.contains('!'));
        assertFalse("Should not find character not present", sb.contains('?'));
    }

    @Test
    public void testContains_AfterAppend() {
        StrBuilder sb = new StrBuilder();
        sb.append("test");
        assertTrue("Should return true after appending", sb.contains('t'));
        sb.append('z');
        assertTrue("Should return true after appending more", sb.contains('z'));
    }

    @Test
    public void testContains_AfterDelete() {
        StrBuilder sb = new StrBuilder("apple");
        assertTrue("Initially contains 'p'", sb.contains('p'));
        sb.delete(1, 3); // removes 'pp'
        assertFalse("Should return false after deleting the character", sb.contains('p'));
    }
}
